"""Reader for DB sources generated by this tool - and only those.

This is deliberately not a Siemens parser: it checks the generator header and then
reads the assignment lines our own template writes.
"""

from __future__ import annotations

import re
from dataclasses import dataclass
from pathlib import Path

from layerpattern.domain.export_model import FORMAT_NAME, FORMAT_VERSION
from layerpattern.domain.linear import LinearForm
from layerpattern.domain.model import MAX_PATTERN_ID, ORIENTATIONS
from layerpattern.domain.rational import NotRepresentable, parse_decimal

_FORMAT = re.compile(r"^//\s*Format\s*:\s*" + re.escape(FORMAT_NAME) + r"\s+(\d+)\s*$", re.M)
_PROJECT = re.compile(r"^//\s*Project\s*:\s*(.*?)\s*$", re.M)
_DB = re.compile(r'^DATA_BLOCK\s+"([^"]+)"', re.M)
_INDEX = re.compile(r"PatternIndex\[(\d+)\]\.(FirstPackageIndex|PackageCount)\s*:=\s*(\d+)\s*;")
_PACKAGE = re.compile(r"Package\[(\d+)\]\.(BaseOrientation|KxL|KxB|KxD|KyL|KyB|KyD)"
                      r"\s*:=\s*([-+0-9.eE]+)\s*;")
_FIELDS = ("BaseOrientation", "KxL", "KxB", "KxD", "KyL", "KyB", "KyD")


class DbImportError(Exception):
    """Not a DB generated by this tool, or damaged; the message is meant for the user."""


@dataclass(frozen=True, slots=True)
class ImportedPattern:
    pattern_id: int
    packages: tuple[tuple[int, LinearForm, LinearForm], ...]   # (orientation, x, y) in sequence


@dataclass(frozen=True, slots=True)
class ImportedDb:
    db_name: str
    project_name: str
    patterns: tuple[ImportedPattern, ...]      # ascending PatternId


def parse(text: str) -> ImportedDb:
    match = _FORMAT.search(text)
    if match is None:
        raise DbImportError(f"The file was not generated by this tool (no '{FORMAT_NAME}' header).")
    if int(match.group(1)) != FORMAT_VERSION:
        raise DbImportError(f"Unsupported exchange format version {match.group(1)} "
                            f"(expected {FORMAT_VERSION}).")
    db = _DB.search(text)
    if db is None:
        raise DbImportError("The file contains no DATA_BLOCK.")
    project = _PROJECT.search(text)

    index: dict[int, dict[str, int]] = {}
    for pid, field, value in _INDEX.findall(text):
        index.setdefault(int(pid), {})[field] = int(value)
    packages: dict[int, dict[str, str]] = {}
    for gidx, field, value in _PACKAGE.findall(text):
        packages.setdefault(int(gidx), {})[field] = value

    patterns = []
    for pid in sorted(index):
        entry = index[pid]
        first, count = entry.get("FirstPackageIndex", 0), entry.get("PackageCount", 0)
        if count == 0:
            continue
        if not 1 <= pid <= MAX_PATTERN_ID:
            raise DbImportError(f"PatternId {pid} is out of range.")
        rows = []
        for gidx in range(first, first + count):
            fields = packages.get(gidx)
            if fields is None or any(f not in fields for f in _FIELDS):
                raise DbImportError(f"Package {gidx} of PatternId {pid} is incomplete.")
            orientation = int(float(fields["BaseOrientation"]))
            if orientation not in ORIENTATIONS:
                raise DbImportError(f"Package {gidx}: BaseOrientation must be 0 or 90.")
            try:
                c = [parse_decimal(fields[f]) for f in _FIELDS[1:]]
            except NotRepresentable as exc:
                raise DbImportError(f"Package {gidx}: {exc}.") from exc
            rows.append((orientation, LinearForm(*c[:3]), LinearForm(*c[3:])))
        patterns.append(ImportedPattern(pid, tuple(rows)))
    if not patterns:
        raise DbImportError("The DB contains no patterns.")
    return ImportedDb(db.group(1), project.group(1) if project else "", tuple(patterns))


def read(path: str | Path) -> ImportedDb:
    try:
        raw = Path(path).read_bytes()
    except OSError as exc:
        raise DbImportError(f"Cannot read the file: {exc.strerror or exc}.") from exc
    try:
        return parse(raw.decode("ascii"))
    except UnicodeDecodeError as exc:
        raise DbImportError("The file is not plain ASCII, so it was not generated by this tool.") from exc
